import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.DxR7mb1F.js";const l="/bluebook/cases/workbuddy-co-create-wechat.png",p=JSON.parse('{"title":"WorkBuddy 社区案例集","description":"汇集 WorkBuddy 用户提交的真实案例，了解不同场景使用了哪些 Skills、如何执行以及最终呈现了什么效果。","frontmatter":{"title":"WorkBuddy 社区案例集","description":"汇集 WorkBuddy 用户提交的真实案例，了解不同场景使用了哪些 Skills、如何执行以及最终呈现了什么效果。","breadcrumbTitle":"社区案例集","aside":false,"outline":false,"pageClass":"community-cases-page"},"headers":[],"relativePath":"cases/index.md","filePath":"cases/index.md","lastUpdated":1786808975000}'),i={name:"cases/index.md"};function r(c,e,d,n,u,k){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="workbuddy-社区案例集" tabindex="-1">WorkBuddy 社区案例集 <a class="header-anchor" href="#workbuddy-社区案例集" aria-label="Permalink to &quot;WorkBuddy 社区案例集&quot;">​</a></h1><p>这里收录由 WorkBuddy 用户提交的真实实践。每个案例都会说明它解决了什么场景、使用了哪些 Skills、在 WorkBuddy 中怎样执行，以及最终交付了什么结果。</p><p>社区案例通过完整性、安全性和可读性审核后即可发布；经过进一步复现和编辑的经典任务，未来可能被收录进《WorkBuddy 实战蓝皮书》正文。</p><h2 id="如何提交-case" tabindex="-1">如何提交 Case <a class="header-anchor" href="#如何提交-case" aria-label="Permalink to &quot;如何提交 Case&quot;">​</a></h2><ol><li>先搜索左侧的社区 Case 和<a href="/bluebook/bluebook/">蓝皮书目录</a>，确认场景或任务没有重复。</li><li>阅读<a href="/bluebook/community/case-contributing">Case 投稿指南</a>，复制标准模板。</li><li>在 <code>docs/cases/submissions/</code> 下新增一个 Case 文件夹。</li><li>写清场景、使用的 Skills、操作过程、实际效果和验收标准。</li><li>本地构建通过后提交 Pull Request，审核合并后会自动出现在左侧案例目录和本页列表中。</li></ol><div class="warning custom-block"><p class="custom-block-title">提交前请自行检查</p><p>如果已有 Case 使用相同目标和流程，请优先补充原案例；如果使用了不同的 Skill、方法或交付方式，请在 PR 中明确说明差异。</p></div><div class="case-intro-actions"><a class="case-intro-button case-intro-button--primary" href="/community/case-contributing">提交你的 Case</a><a class="case-intro-button" href="/bluebook/">阅读蓝皮书</a></div><section class="case-co-create" aria-labelledby="case-co-create-title"><div class="case-co-create__copy"><p class="case-co-create__label">CONTRIBUTOR COMMUNITY</p><h2 id="case-co-create-title">提交 PR 后，加入 WorkBuddy 共创群</h2><p>如果你正在准备或已经提交 Case PR，欢迎添加微信。我们会邀请你进入 WorkBuddy 共创群，一起讨论案例结构、复现过程、审核建议和蓝皮书后续选题。</p><strong>添加微信时，请备注：workbuddy共创</strong><ul><li>交流 Case 选题，避免重复提交。</li><li>讨论 Skill、操作步骤和结果证明。</li><li>获取 PR 审核和内容完善建议。</li><li>参与经典 Case 进入蓝皮书正文的共创。</li></ul></div><a class="case-co-create__qr" href="/cases/workbuddy-co-create-wechat.png" target="_blank" rel="noreferrer" aria-label="查看 WorkBuddy 共创联系人微信二维码大图"><img src="'+l+'" alt="刘聪NLP 微信二维码，添加时备注 workbuddy共创" loading="lazy"><span>扫码添加微信 · 备注“workbuddy共创”</span></a></section><div class="case-editor-note"><strong>从社区案例到蓝皮书正文</strong><p>我们会持续观察案例的可复现性、代表性和读者反馈。通过二次验证的经典任务，将在保留原作者署名的前提下进入蓝皮书正式章节。</p></div>',9)])])}const _=a(i,[["render",r]]);export{p as __pageData,_ as default};
